const int trigPin = 7, echoPin = 6, ledPin = 13;

void setup() {
  pinMode(trigPin, OUTPUT); pinMode(echoPin, INPUT); pinMode(ledPin, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  digitalWrite(trigPin, LOW); delayMicroseconds(2);
  digitalWrite(trigPin, HIGH); delayMicroseconds(10); digitalWrite(trigPin, LOW);
  long duration = pulseIn(echoPin, HIGH, 30000);
  float distance = duration * 0.0343 / 2.0;
  Serial.println(distance);
  digitalWrite(ledPin, duration > 0 && distance < 20 ? HIGH : LOW);
  delay(100);
}

#include <DHT.h>
#define DHTPIN 4
#define DHTTYPE DHT11
DHT dht(DHTPIN, DHTTYPE);

void setup() {
  Serial.begin(9600); dht.begin();
}

void loop() {
  float humidity = dht.readHumidity();
  float temperature = dht.readTemperature();
  if (isnan(humidity) || isnan(temperature)) {
    Serial.println("Sensor read failed");
  } else {
    Serial.print(temperature); Serial.print(" C, ");
    Serial.print(humidity); Serial.println(" %");
  }
  delay(2000);
}

const int trigPin=7, echoPin=6;
const int in1=4, in2=5, in3=8, in4=9;

void drive(int a, int b, int c, int d) {
  digitalWrite(in1,a); digitalWrite(in2,b); digitalWrite(in3,c); digitalWrite(in4,d);
}

float distanceCm() {
  digitalWrite(trigPin,LOW); delayMicroseconds(2);
  digitalWrite(trigPin,HIGH); delayMicroseconds(10); digitalWrite(trigPin,LOW);
  return pulseIn(echoPin,HIGH,30000) * 0.0343 / 2.0;
}

void setup() {
  pinMode(trigPin,OUTPUT); pinMode(echoPin,INPUT);
  pinMode(in1,OUTPUT); pinMode(in2,OUTPUT); pinMode(in3,OUTPUT); pinMode(in4,OUTPUT);
}

void loop() {
  float d=distanceCm();
  if (d > 0 && d < 20) {
    drive(LOW,HIGH,LOW,HIGH); delay(350);
    drive(HIGH,LOW,LOW,HIGH); delay(450);
  } else { drive(HIGH,LOW,HIGH,LOW); }
}

