const int leftLdr=A0, rightLdr=A1;
const int in1=4, in2=5, in3=6, in4=7;

void motors(bool lf, bool lb, bool rf, bool rb) {
  digitalWrite(in1,lf); digitalWrite(in2,lb);
  digitalWrite(in3,rf); digitalWrite(in4,rb);
}
void setup() {
  pinMode(in1,OUTPUT); pinMode(in2,OUTPUT); pinMode(in3,OUTPUT); pinMode(in4,OUTPUT);
}
void loop() {
  int left=analogRead(leftLdr), right=analogRead(rightLdr);
  int difference=left-right;
  if (abs(difference)<50) motors(HIGH,LOW,HIGH,LOW);
  else if (difference>0) motors(LOW,LOW,HIGH,LOW);
  else motors(HIGH,LOW,LOW,LOW);
}

#include <Wire.h>
#include <RTClib.h>
#include <LiquidCrystal_I2C.h>
RTC_DS3231 rtc;
LiquidCrystal_I2C lcd(0x27, 16, 2);

void setup() {
  lcd.init(); lcd.backlight();
  if (!rtc.begin()) { lcd.print("RTC not found"); while (true) {} }
  // Run once if needed, then comment out and upload again:
  // rtc.adjust(DateTime(F(__DATE__), F(__TIME__)));
}

void loop() {
  DateTime now = rtc.now();
  lcd.setCursor(0,0);
  if (now.hour()<10) lcd.print('0'); lcd.print(now.hour()); lcd.print(':');
  if (now.minute()<10) lcd.print('0'); lcd.print(now.minute()); lcd.print(':');
  if (now.second()<10) lcd.print('0'); lcd.print(now.second());
  lcd.setCursor(0,1);
  lcd.print(now.day()); lcd.print('/'); lcd.print(now.month()); lcd.print('/'); lcd.print(now.year());
  delay(500);
}
